import type { System } from "../../Engine/System";
import type { World } from "../../Engine/World";
import type { Bullet } from "../Entity/Bullet";
import type { Plane } from "../Entity/Plane";

export class MovementSystem implements System{
    
    onTick(world:World,dt:number): void{
        this._tickBullets(world, dt);
        this._tickEnemies(world, dt);
    }

    private _tickBullets(world: World, dt: number): void {
        for(const b of world.query<Bullet>('bullet')){
            b.x +=  b.dirX * b.speed * dt;
            b.y +=  b.dirY * b.speed * dt;
        }
    }

    private _tickEnemies(world: World, dt: number): void {
        for(const p of world.query<Plane>('enemy')){
            switch(p.movePattern){
                case 'straight':
                    this._moveStraight(p, dt);
                    break;
                case 'sine':
                    this._moveSine(p, dt);
                    break;
                case 'none':
                default:
                    // 不动
                    break;
            }
        }
    }

    private _moveStraight(p: Plane, dt: number): void {
        p.x -= p.moveSpeed * dt;
    }

    private _moveSine(p: Plane, dt: number): void{
        p.y -= p.moveSpeed * dt;
        p.patternPhase += 3 * dt;                        // 摆动频率
        p.x = p.baseX + Math.sin(p.patternPhase) * 80;    // 摆动幅度 80 像素
    }
}


